String fn0(String stream, int chunkSize) {
  List<String> chunks = stream.substring(0, stream.length - 1).split('|');
  List<int> heights = [];
  List<int> widths = [];
  List<String> codes = [];
  for (String chunk in chunks) {
    List<String> parts = chunk.split(',');
    int h = int.parse(parts[0]);
    int w = int.parse(parts[1]);
    int code = int.parse(parts[2]);
    heights.add(h);
    widths.add(w);
    codes.add(String.fromCharCode(code));
  }
  List<int> xLengths = List.filled(codes.length, 0);
  int xStart = 0;
  for (int i = 0; i < codes.length; i++) {
    int xEnd = xStart + widths[i] - 1;
    if (xEnd > 0 && heights[i] == heights[xEnd]) {
      xLengths[i] = xEnd - xStart + 1;
    }
    xStart = xEnd + 1;
  }
  int total = 0;
  for (int len in xLengths) {
    if (len > 0) total += len;
  }
  return '$total:${total > 0 ? total / chunkSize : 0}';
}

