void expect(dynamic a, dynamic b) {
  if (a == b) return;

  if (a is List && b is List) {
    expectList(a, b);
  } else if (a is Map && b is Map) {
    expectMap(a, b);
  } else if (a is Set && b is Set) {
    expectSet(a, b);
  } else {
    throw '$a != $b';
  }
}

void expectSet(Set a, Set b) {
  if (a.length != b.length) throw 'set lengths are not equal';

  for (var v in a) {
    if (!b.contains(v)) throw '$v not in $b';
  }
}

void expectList(List a, List b) {
  if (a.length != b.length) throw 'list lengths are not equal';

  for (var i = 0; i < a.length; i++) {
    expect(a[i], b[i]);
  }
}

void expectMap(Map a, Map b) {
  if (a.length != b.length) throw 'map lengths are not equal';

  for (var key in a.keys) {
    expect(a[key], b[key]);
  }
}
